/* =======================================================================
   downloads-data.js — os 3 wallpapers das campanhas, já codificados em
   base64 (data URI), a partir de img/wallpaper-hero.jpg de cada campanha.

   Por quê: esta página é aberta localmente (file://), e nesse protocolo o
   atributo "download" do HTML e possibilidades como fetch()/canvas para
   outro arquivo local são bloqueados pelo navegador por segurança — o link
   simplesmente abre a imagem, sem baixar nada de verdade. Um data URI não
   sofre essa restrição: o navegador honra o "download" normalmente, então
   o clique baixa o arquivo de fato, com a janela nativa de "Salvar como".
   ======================================================================= */
window.RPG_WALLPAPERS = {
  rpg1: "data:image/jpeg;base64,",
  rpg2: "data:image/jpeg;base64,",
  rpg3: "data:image/jpeg;base64,",
};
